if(!document.PathName.EndsWith("Leichhardt_Coordination_Model.rvt")) throw new Exception("Unexpected active model");
using(var tx=new Transaction(document,"Leichhardt - architectural reference datums")) {
 tx.Start();
 var mm=UnitTypeId.Millimeters;
 Func<double,double> ft=x=>UnitUtils.ConvertToInternalUnits(x,mm);
 var existing=new FilteredElementCollector(document).OfClass(typeof(Level)).Cast<Level>().ToList();
 var ground=existing.Single(l=>l.Id.Value==30); ground.Name="00 Ground FFL - RL 10.906"; ground.Elevation=0;
 var first=existing.Single(l=>l.Id.Value==9946); first.Name="01 First FFL - ARCH 3140"; first.Elevation=ft(3140);
 var definitions=new[]{("00 Garage Alfresco FFL",-86.0),("00 Ground Ceiling - ARCH",2740.0),("01 First Ceiling - ARCH",5730.0)};
 foreach(var def in definitions) {
  var l=Level.Create(document,ft(def.Item2)); l.Name=def.Item1;
  l.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS)?.Set("Architectural A07/A12. Local GF=0 corresponds to RL10.906. Floor-zone discrepancy D01 unresolved; reference datum only.");
 }
 ground.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS)?.Set("A07/A12 FFL10.906. Local modelling datum. No surveyed XY coordinates acquired.");
 first.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS)?.Set("A12:2740 ceiling+400 floor zone=3140. D01: supplier 413 deep joists; S10 notes 300 deep. Architectural reference only.");
 var planType=new FilteredElementCollector(document).OfClass(typeof(ViewFamilyType)).Cast<ViewFamilyType>().First(x=>x.ViewFamily==ViewFamily.FloorPlan);
 foreach(var level in new[]{ground,first}) {
  var v=ViewPlan.Create(document,planType.Id,level.Id); v.Name=level==ground?"02 Proposed - Ground Coordination":"02 Proposed - First Coordination"; v.Scale=100; v.DetailLevel=ViewDetailLevel.Fine;
 }
 var draftingType=new FilteredElementCollector(document).OfClass(typeof(ViewFamilyType)).Cast<ViewFamilyType>().First(x=>x.ViewFamily==ViewFamily.Drafting);
 var note=ViewDrafting.Create(document,draftingType.Id); note.Name="00 Coordination - Model Status"; note.Scale=1;
 var textType=new FilteredElementCollector(document).OfClass(typeof(TextNoteType)).FirstElementId();
 TextNote.Create(document,note.Id,XYZ.Zero,ft(240),"LEICHHARDT COORDINATION\nReference setup in progress - proposed architecture, primary structure and detailed timber/truss members.\nGround local Z=0 = architectural RL10.906. Surveyed XY origin is unverified.\nArchitectural A12 first FFL +3140 and first ceiling +5730 retained as reference datums.\nD01: 400 architectural floor zone vs 413 supplier joists; S10 specifies 300-deep posi-struts or equivalent.\nD02: porch RL10.734 implies 172 mm below GF; A07 also labels 226 mm step.\nSources: architecture construction issue20.01.2024; engineer C1 03.12.2025; supplier K0964 layouts03.04.2026, details10.04.2026.\nDetailed source and discrepancy registers: output/revit.\nNOT A COMPLETED OR VERIFIED CONSTRUCTION MODEL.",textType);
 document.ProjectInformation.Name="Leichhardt - Proposed Dwelling Coordination";
 document.ProjectInformation.Number="042224 / 25565-24 / K0964";
 document.ProjectInformation.Address="Lot 735 (No. 15) Leichhardt Avenue, Burnside Heights VIC";
 tx.Commit();
}
document.Save();
return new {levels=new FilteredElementCollector(document).OfClass(typeof(Level)).Cast<Level>().Select(l=>new{name=l.Name,mm=l.Elevation*304.8}).ToArray(),saved=document.PathName};

